import json
import math
from pathlib import Path


def _check_finite(value):
    if isinstance(value, bool):
        raise ValueError("boolean is not a finite number")
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("non-finite number")
        return value
    raise ValueError("not a number")


def load_payload(path):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    try:
        data = json.loads(text, parse_constant=lambda s: (_ for _ in ()).throw(ValueError("non-finite JSON")))
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError("invalid JSON") from exc
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level must be object or array")
    return data

import copy


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")

    payload = payloads[0]
    # The input is the fit_members result wrapper: {"name":..., "result": {...}}
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        data = payload["result"]
    else:
        data = payload

    if not isinstance(data, dict):
        raise ValueError("fit result must be an object")

    classes = data["classes"]
    members = data["members"]

    if not isinstance(classes, list) or not classes:
        raise ValueError("classes must be a non-empty list")
    if not isinstance(members, list):
        raise ValueError("members must be a list")

    sample_count = len(classes) and None
    # determine sample count from first member predictions
    sample_count = None
    for m in members:
        preds = m["predictions"]
        if sample_count is None:
            sample_count = len(preds)
        elif len(preds) != sample_count:
            raise ValueError("inconsistent sample count")

    if sample_count is None:
        sample_count = 0

    n_classes = len(classes)
    class_index = {c: i for i, c in enumerate(classes)}

    # scores[sample][class_index]
    scores = [[0.0] * n_classes for _ in range(sample_count)]

    for m in members:
        weight = m["fit_weight"]
        preds = m["predictions"]
        for s in range(sample_count):
            label = preds[s]
            if label not in class_index:
                raise ValueError("label not in global classes")
            scores[s][class_index[label]] += weight

    predictions = []
    for s in range(sample_count):
        row = scores[s]
        best = max(row)
        # tie-break by global classes order
        idx = row.index(best)
        predictions.append(classes[idx])

    return {"name": contract["name"], "result": {"predictions": predictions, "scores": scores}}

import copy
import math


def _is_finite_number(v):
    if isinstance(v, bool):
        return False
    if isinstance(v, int):
        return True
    if isinstance(v, float):
        return math.isfinite(v)
    return False


def _is_nonneg_number(v):
    return _is_finite_number(v) and v >= 0


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")
    payload = payloads[0]
    if not isinstance(payload, dict):
        raise ValueError("input must be object")

    # Unwrap name/result envelope if present.
    if set(payload.keys()) == {"name", "result"}:
        data = payload["result"]
    else:
        data = payload
    if not isinstance(data, dict):
        raise ValueError("business input must be object")

    classes = data.get("classes")
    sample_weight = data.get("sample_weight")
    members = data.get("members")

    if not isinstance(classes, list) or not classes:
        raise ValueError("classes required non-empty list")
    seen = set()
    for c in classes:
        if not isinstance(c, str) or not c.strip():
            raise ValueError("class must be non-empty string")
        if c in seen:
            raise ValueError("duplicate class")
        seen.add(c)

    if not isinstance(sample_weight, list):
        raise ValueError("sample_weight must be list")
    for w in sample_weight:
        if not _is_nonneg_number(w):
            raise ValueError("sample_weight must be non-negative number")
    sample_count = len(sample_weight)

    if not isinstance(members, list):
        raise ValueError("members must be list")

    ids = set()
    active_members = []
    for m in members:
        if not isinstance(m, dict):
            raise ValueError("member must be object")
        if "id" not in m or "active" not in m:
            raise ValueError("member missing id/active")
        mid = m["id"]
        if not isinstance(mid, str) or not mid.strip():
            raise ValueError("member id must be non-empty string")
        if mid in ids:
            raise ValueError("duplicate member id")
        ids.add(mid)
        if not isinstance(m["active"], bool):
            raise ValueError("active must be bool")
        if not m["active"]:
            continue
        active_members.append(m)

    if not active_members:
        raise ValueError("at least one active member required")

    total_weight = 0.0
    for m in active_members:
        w = m.get("weight")
        if not _is_nonneg_number(w):
            raise ValueError("member weight must be non-negative number")
        total_weight += w
    if total_weight <= 0:
        raise ValueError("active member weight sum must be > 0")

    for m in active_members:
        preds = m.get("predictions")
        mclasses = m.get("classes")
        probs = m.get("probabilities")
        if not isinstance(preds, list) or len(preds) != sample_count:
            raise ValueError("predictions length must equal sample count")
        for p in preds:
            if p not in classes:
                raise ValueError("prediction label not in global classes")
        if not isinstance(mclasses, list) or sorted(mclasses) != sorted(classes):
            raise ValueError("member classes must be permutation of global classes")
        if not isinstance(probs, list) or len(probs) != sample_count:
            raise ValueError("probabilities rows must equal sample count")
        for row in probs:
            if not isinstance(row, list) or len(row) != len(mclasses):
                raise ValueError("probability row length mismatch")
            s = 0.0
            for v in row:
                if not _is_nonneg_number(v):
                    raise ValueError("probability must be non-negative number")
                s += v
            if abs(s - 1.0) > 1e-9:
                raise ValueError("probability row must sum to 1")

    result_members = []
    for m in active_members:
        nm = copy.deepcopy(m)
        nm["fit_weight"] = copy.deepcopy(sample_weight)
        result_members.append(nm)

    return {
        "name": contract["name"],
        "result": {
            "classes": copy.deepcopy(classes),
            "sample_count": sample_count,
            "members": result_members,
        },
    }

import math


def _is_finite_number(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, int):
        return True
    if isinstance(value, float):
        return math.isfinite(value)
    return False


def transform(payloads, contract):
    if not isinstance(payloads, list) or len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")
    if len(payloads) != 1:
        raise ValueError("soft_vote expects exactly one input")

    payload = payloads[0]
    # When the input object has exactly keys name/result, only result is business input.
    if isinstance(payload, dict) and set(payload.keys()) == {"name", "result"}:
        data = payload["result"]
    else:
        data = payload

    if not isinstance(data, dict):
        raise ValueError("input must be an object")

    classes = data.get("classes")
    members = data.get("members")
    if not isinstance(classes, list) or not isinstance(members, list):
        raise ValueError("missing classes or members")

    if len(classes) == 0:
        raise ValueError("classes must be non-empty")
    for c in classes:
        if not isinstance(c, str) or not c.strip():
            raise ValueError("invalid class label")
    if len(set(classes)) != len(classes):
        raise ValueError("duplicate classes")

    n_classes = len(classes)
    class_index = {c: i for i, c in enumerate(classes)}

    sample_count = None
    for m in members:
        if not isinstance(m, dict):
            raise ValueError("member must be object")
        probs = m.get("probabilities")
        mclasses = m.get("classes")
        weight = m.get("weight")
        if not isinstance(probs, list) or not isinstance(mclasses, list):
            raise ValueError("member missing probabilities/classes")
        if not _is_finite_number(weight) or weight < 0:
            raise ValueError("invalid member weight")
        if len(mclasses) != n_classes or set(mclasses) != set(classes):
            raise ValueError("member classes must be a permutation of global classes")
        if sample_count is None:
            sample_count = len(probs)
        elif len(probs) != sample_count:
            raise ValueError("inconsistent sample count")

    if sample_count is None:
        sample_count = 0

    # Accumulate weighted probabilities mapped to global class order.
    totals = [[0.0] * n_classes for _ in range(sample_count)]
    weight_sum = 0.0
    for m in members:
        weight = m["weight"]
        weight_sum += weight
        mclasses = m["classes"]
        probs = m["probabilities"]
        # column order of this member's probabilities follows mclasses
        for s in range(sample_count):
            row = probs[s]
            if not isinstance(row, list) or len(row) != n_classes:
                raise ValueError("probability row size mismatch")
            for col, cls in enumerate(mclasses):
                p = row[col]
                if not _is_finite_number(p) or p < 0:
                    raise ValueError("invalid probability")
                totals[s][class_index[cls]] += weight * p

    if weight_sum <= 0:
        raise ValueError("total weight must be positive")

    probabilities = []
    predictions = []
    for s in range(sample_count):
        row = [totals[s][i] / weight_sum for i in range(n_classes)]
        probabilities.append(row)
        best = max(range(n_classes), key=lambda i: row[i])
        predictions.append(classes[best])

    return {"name": contract["name"], "result": {"predictions": predictions, "probabilities": probabilities}}

